import java.util.Scanner;

public class Main {
    static String sakkizBit(int o) {
        return String.format("%8s", Integer.toBinaryString(o)).replace(' ', '0');
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        in.useDelimiter("[^0-9]+");
        int a = in.nextInt();
        int b = in.nextInt();
        int c = in.nextInt();
        int d = in.nextInt();
        long son = (long) a * 16777216 + (long) b * 65536 + (long) c * 256 + d;
        System.out.println(sakkizBit(a) + "." + sakkizBit(b) + "." + sakkizBit(c) + "." + sakkizBit(d));
        System.out.println(son);
    }
}

